function AuctionModule({ role, mode }: { role: Role; mode: "auction" | "sold" | "unsold" }) {
  const router = useRouter()
  const candidates = usePplStore((s) => s.candidates)
  const teams = usePplStore((s) => s.teams)
  const history = usePplStore((s) => s.bidHistory)
  const currentBid = usePplStore((s) => s.currentBid)
  const highestTeam = usePplStore((s) => s.highestTeam)
  const activeCandidateId = usePplStore((s) => s.activeCandidate)
  const paused = usePplStore((s) => s.paused)
  const bid = usePplStore((s) => s.bid)
  const resolve = usePplStore((s) => s.resolveAuction)
  const setActive = usePplStore((s) => s.setActiveCandidate)
  const updateCandidate = usePplStore((s) => s.updateCandidate)
  const togglePaused = usePplStore((s) => s.togglePaused)
  const notify = usePplStore((s) => s.notify)
  const viewer = role === "viewer" || role === "player"
  const listMode = mode !== "auction"
  const [timer, setTimer] = useState(30)
  const [filter, setFilter] = useState("")
  const [confirm, setConfirm] = useState<"Sold" | "Unsold" | null>(null)
  const [assignedTeam, setAssignedTeam] = useState(String(highestTeam || 1))
  const [increment, setIncrement] = useState(0.5)
  const stageRef = useRef<HTMLDivElement>(null)
  const active = candidates.find((candidate) => candidate.id === activeCandidateId) ?? candidates.find((candidate) => candidate.status === "Available") ?? candidates[0]
  useEffect(() => { if (!stageRef.current) return; const ctx = gsap.context(() => { gsap.fromTo(".auction-reveal", { opacity: 0, y: 18 }, { opacity: 1, y: 0, duration: .55, stagger: .08, ease: "power2.out" }) }, stageRef); return () => ctx.revert() }, [activeCandidateId])
  useEffect(() => { if (paused || viewer || mode !== "auction") return; const interval = window.setInterval(() => setTimer((value) => value <= 0 ? 30 : value - 1), 1000); return () => window.clearInterval(interval) }, [paused, viewer, mode, activeCandidateId])
  const list = candidates.filter((candidate) => candidate.status === (mode === "sold" ? "Sold" : "Unsold")).filter((candidate) => `${candidate.name} ${candidate.category} ${candidate.country}`.toLowerCase().includes(filter.toLowerCase()))
  const act = (status: "Sold" | "Unsold") => { const chosen = status === "Sold" ? Number(assignedTeam) : undefined; resolve(status, chosen); setConfirm(null); setTimer(30); const next = candidates.find((candidate) => candidate.status === "Available" && candidate.id !== active.id); if (next) setActive(next.id) }
  if (listMode) return <><PageHeader eyebrow={`AUCTION / ${mode.toUpperCase()} REGISTER`} title={mode === "sold" ? "The sold register." : "Back in the pool."} description={mode === "sold" ? "Completed fictional demo allocations with franchise and purchase price." : "Unpicked candidates available to reintroduce to the demo auction."} action={<Link href={`/${role}/auction`} className="app-button primary"><Gavel size={15} /> Open auction room</Link>} /><div className="module-toolbar"><div className="search-field"><Search size={16} /><input value={filter} onChange={(e) => setFilter(e.target.value)} placeholder="Search the register..." aria-label="Search auction register" /></div><span className="toolbar-count">{list.length} CANDIDATES</span></div><SectionCard title={mode === "sold" ? "Transaction ledger" : "Unsold candidate pool"}><SimpleTable headers={mode === "sold" ? ["CANDIDATE", "FRANCHISE", "CATEGORY", "PURCHASE PRICE", "TIME", "DETAILS"] : ["CANDIDATE", "BASE PRICE", "CATEGORY", "RATING", "HISTORY", "ACTION"]}>{list.map((candidate) => <tr key={candidate.id}><td><span className="table-person"><b>{candidate.photo ? <img src={candidate.photo} alt={`${candidate.name} candidate portrait`} /> : candidate.initials}</b><span><strong>{candidate.name}</strong><small>{candidate.country} · fictional profile</small></span></span></td>{mode === "sold" ? <><td><span className="table-team"><TeamBadge id={candidate.teamId ?? 1} />{getTeam(candidate.teamId ?? 1).name}</span></td><td>{candidate.category}</td><td><strong>{currency(candidate.price ?? 0)}</strong></td><td>14:32:08</td><td><StatusPill status="green">COMPLETED</StatusPill></td></> : <><td>{formatPrice(candidate.basePrice)}</td><td>{candidate.category}</td><td>{candidate.rating} OVR</td><td>Round 1 · no bids</td><td><button className="table-link button-link" onClick={() => { updateCandidate(candidate.id, { status: "Available" }); setActive(candidate.id); notify(`${candidate.name} returned to the auction queue.`); router.push(`/${role}/auction`) }}>Reintroduce <ArrowUpRight size={13} /></button></td></>}</tr>)}</SimpleTable></SectionCard></>
  return <><PageHeader eyebrow={`${roleMeta[role].label.toUpperCase()} / LIVE AUCTION`} title="The auction room." description="An interactive local simulation. Bids, timing and results are not live or shared across users." action={role === "admin" && <button className={`app-button ${paused ? "primary" : "secondary"}`} onClick={togglePaused}>{paused ? <Play size={15} /> : <Pause size={15} />}{paused ? "Resume auction" : "Pause auction"}</button>} />
    <div className="auction-warning"><Radio size={16} /><span><strong>SIMULATION MODE</strong> Auction activity is local to this browser session. No real-time bidders or backend connection.</span><StatusPill status="red">NOT LIVE</StatusPill></div>
    <div className="auction-workspace">
      <div className="auction-stage-column"><div className="auction-stage" ref={stageRef}><div className="auction-stage-head"><span><span className="stage-dot" /> {paused ? "AUCTION PAUSED" : viewer ? "VIEWING AUCTION" : "LOT ON THE FLOOR"}</span><span>LOT #{String(active.id).padStart(3, "0")}</span></div><div className="auction-player"><div className="auction-player-orb">{active.photo ? <img src={active.photo} alt={`${active.name} candidate portrait`} /> : <span>{active.initials}</span>}<b>{active.rating}</b></div><div className="auction-player-detail auction-reveal"><span className="candidate-id">PPL CANDIDATE · {active.country.toUpperCase()}</span><h2>{active.name}</h2><p>{active.category} <i>·</i> {active.country}</p><div className="candidate-metadata"><span><small>PARTY</small>{active.party}</span><span><small>BAT</small>{active.batting}<i className="attribute-mini"><b style={{ width: `${active.batting}%` }} /></i></span><span><small>BOWL</small>{active.bowling}<i className="attribute-mini"><b style={{ width: `${active.bowling}%` }} /></i></span></div></div></div><div className="auction-price-row"><div><span>BASE PRICE</span><strong>{formatPrice(active.basePrice)}</strong></div><div className="current-bid"><span>CURRENT BID</span><strong>{currency(currentBid || active.basePrice)}</strong>{highestTeam > 0 && <small>LEADING: {getTeam(highestTeam).name}</small>}</div><div className="auction-clock"><Clock3 size={15} /><strong>00:{String(timer).padStart(2, "0")}</strong></div></div>{paused && <div className="auction-paused-cover">AUCTION PAUSED</div>}</div>
        <SectionCard title="Franchise bidding panel" action={<span className="table-link">PURSE REMAINING <ArrowDownRight size={13} /></span>}>{!viewer && <div className="bid-increment-controls"><span>BID INCREMENT</span>{[0.5, 1, 2].map((step) => <button type="button" key={step} aria-pressed={increment === step} className={increment === step ? "selected" : ""} onClick={() => setIncrement(step)}>+ {step.toFixed(1)}</button>)}<small>LAKHS</small></div>}<div className="bidding-team-grid">{teams.map((team) => <button key={team.id} className={`bidding-team ${highestTeam === team.id ? "is-leading" : ""}`} onClick={() => !viewer && !paused && (role === "admin" || team.id === 1) && bid(team.id, increment)} disabled={viewer || paused || (role === "owner" && team.id !== 1)}><TeamBadge id={team.id} /><span><strong>{team.name}</strong><small>{currency(team.purse)} left</small></span>{highestTeam === team.id ? <Crown size={15} /> : <span className="bid-increment">+ {increment.toFixed(1)}</span>}</button>)}</div>{viewer && <p className="muted-copy">View-only screen. Bidding controls are disabled.</p>}</SectionCard>
      </div>
      <aside className="auction-side-column"><SectionCard title="Bid history" action={<span className="demo-tag">LOCAL</span>}><div className="bid-history-list">{history.slice(0, 7).map((entry, i) => <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} key={`${entry.time}-${i}`} className="bid-history-row"><span className="bid-history-num">{String(i + 1).padStart(2, "0")}</span><div><strong>{entry.team}</strong><small>{entry.candidate} · {entry.time}</small></div><b>{currency(entry.amount)}</b></motion.div>)}</div></SectionCard>
        <SectionCard title="Up next" action={<span className="table-link">{candidates.filter((c) => c.status === "Available").length} AVAILABLE</span>}><div className="next-candidate-list">{candidates.filter((c) => c.status === "Available" && c.id !== active.id).slice(0, 5).map((candidate) => <button key={candidate.id} onClick={() => { setActive(candidate.id); setTimer(30) }}><span className="next-candidate-initials">{candidate.initials}</span><span><strong>{candidate.name}</strong><small>{candidate.category}</small></span><b>{formatPrice(candidate.basePrice)}</b></button>)}</div></SectionCard>
        {role === "admin" && <div className="auction-result-actions"><button className="app-button sold-action" onClick={() => setConfirm("Sold")}><BadgeCheck size={15} /> Mark as sold</button><button className="app-button unsold-action" onClick={() => setConfirm("Unsold")}><CircleMinus size={15} /> Mark unsold</button></div>}
        <p className="auction-simulation-note">Countdown resets locally. No external auction engine is connected.</p>
      </aside>
    </div>
    {confirm && <div className="modal-backdrop" role="presentation" onClick={() => setConfirm(null)}><div className="edit-modal confirm-modal" role="dialog" aria-modal="true" aria-labelledby="confirm-auction-title" onClick={(e) => e.stopPropagation()}><div className="form-heading"><div><span className="workspace-eyebrow">CONFIRM LOCAL RESULT</span><h2 id="confirm-auction-title">{confirm === "Sold" ? `Allocate ${active.name}?` : `Mark ${active.name} unsold?`}</h2></div><button onClick={() => setConfirm(null)} aria-label="Close confirmation"><X size={18} /></button></div><p>This changes the local demo data only. It does not execute a real transaction.</p>{confirm === "Sold" && <label>ASSIGN FRANCHISE<select value={assignedTeam} onChange={(e) => setAssignedTeam(e.target.value)}>{teams.map((team) => <option value={team.id} key={team.id}>{team.name} · {currency(team.purse)} remaining</option>)}</select></label>}<div className="form-actions"><button className={`app-button ${confirm === "Sold" ? "primary" : "danger"}`} onClick={() => act(confirm)}>Confirm {confirm.toLowerCase()}</button><button className="app-button secondary" onClick={() => setConfirm(null)}>Cancel</button></div></div></div>}
  </>
}

function MatchModule({ role, mode }: { role: Role; mode: "matches" | "fixtures" }) {
  return <MatchCentre role={role} mode={mode} />
}

function Standings() { const allTeams = usePplStore((s) => s.teams); const teams = [...allTeams].sort((a, b) => b.points - a.points); return <><PageHeader eyebrow="TOURNAMENT / TABLE" title="The table takes shape." description="Illustrative points table for the fictional inaugural season. Sample results only." action={<StatusPill status="gold">AFTER ROUND 1</StatusPill>} /><div className="standings-banner"><div><Trophy size={20} /><span>TOP FOUR QUALIFY FOR THE PLAYOFFS</span></div><span>PLAYOFFS <b>·</b> FINAL</span></div><SectionCard title="Tournament standings"><SimpleTable headers={["POS", "TEAM", "P", "W", "L", "PTS", "NRR", "FORM"]}>{teams.map((team, index) => <tr key={team.id}><td><strong className={index < 4 ? "qualified-rank" : "rank-number"}>{String(index + 1).padStart(2, "0")}</strong></td><td><span className="table-team"><TeamBadge id={team.id} />{team.name}</span></td><td>5</td><td>{team.wins}</td><td>{team.losses}</td><td><strong>{team.points}</strong></td><td>{team.nrr}</td><td><span className="form-mini">{["W", "W", "L", "W", "L"].map((result, i) => <i key={i} className={result === "W" ? "win" : "loss"}>{result}</i>)}</span></td></tr>)}</SimpleTable></SectionCard><div className="playoff-cards"><div><span>QUALIFIER 1</span><strong>1st place <i>v</i> 2nd place</strong><small>Top 2 · winner advances directly</small></div><div><span>ELIMINATOR</span><strong>3rd place <i>v</i> 4th place</strong><small>Loser exits · winner earns another chance</small></div><div><span>FINAL</span><strong>The championship</strong><small>One trophy. One inaugural champion.</small></div></div></> }

function OwnerTransactions() {
  const allCandidates = usePplStore((state) => state.candidates)
  const team = usePplStore((state) => state.teams.find((item) => item.id === 1) ?? seedTeams[0])
  const players = allCandidates.filter((candidate) => candidate.teamId === team.id)
  const spend = players.reduce((total, candidate) => total + (candidate.price ?? 0), 0)
  return <><PageHeader eyebrow="TEAM OWNER / FRANCHISE LEDGER" title="Your transactions." description="Only Northern Hawks franchise allocations are shown in this owner workspace." action={<StatusPill status="gold">PRIVATE DEMO VIEW</StatusPill>} /><div className="metrics-grid"><StatCard label="Remaining purse" value={currency(team.purse)} note="Opening balance ₹ 100.0L" icon={TrendingUp} /><StatCard label="Players acquired" value={String(players.length).padStart(2, "0")} note="Assigned to your franchise" icon={Users} tone="blue" /><StatCard label="Total squad spend" value={currency(spend)} note="Local demo allocations" icon={Activity} tone="green" /><StatCard label="Average purchase" value={currency(players.length ? spend / players.length : 0)} note="Per acquired player" icon={Target} tone="purple" /></div><SectionCard title="Franchise transaction history"><SimpleTable headers={["PLAYER", "ROLE", "PURCHASE PRICE", "AUCTION ROUND", "STATUS"]}>{players.map((player) => <tr key={player.id}><td><span className="table-person"><b>{player.initials}</b><span><strong>{player.name}</strong><small>Fictional candidate</small></span></span></td><td>{player.category}</td><td><strong>{currency(player.price ?? 0)}</strong></td><td>Round 1 · 14:28</td><td><StatusPill status="green">CONFIRMED</StatusPill></td></tr>)}</SimpleTable></SectionCard><RecentActivity teamId={team.id} /></>
}

function OwnerStatistics() {
  const allCandidates = usePplStore((state) => state.candidates)
  const team = usePplStore((state) => state.teams.find((item) => item.id === 1) ?? seedTeams[0])
  const players = allCandidates.filter((candidate) => candidate.teamId === team.id)
  return <><PageHeader eyebrow="TEAM OWNER / PERFORMANCE" title="Franchise statistics." description="Squad composition and sample tournament performance for your team." action={<StatusPill status="gold">DEMO METRICS</StatusPill>} /><div className="metrics-grid"><StatCard label="Wins" value={String(team.wins).padStart(2, "0")} note="Inaugural season" icon={Trophy} /><StatCard label="League points" value={String(team.points).padStart(2, "0")} note={`Net run rate ${team.nrr}`} icon={TrendingUp} tone="blue" /><StatCard label="Squad size" value={`${players.length} / ${team.maxSquad}`} note="Roster limit" icon={Users} tone="green" /><StatCard label="Purse remaining" value={currency(team.purse)} note="Of ₹ 100.0L opening purse" icon={Activity} tone="purple" /></div><SectionCard title="Roster breakdown"><div className="category-bars">{["Batter", "Bowler", "All-rounder", "Wicketkeeper"].map((category) => { const count = players.filter((player) => player.category === category).length; return <div className="category-bar-row" key={category}><span>{category}</span><div className="progress-track"><i style={{ width: `${players.length ? Math.max(10, count / players.length * 100) : 0}%` }} /></div><b>{count}</b></div> })}</div></SectionCard><RecentActivity teamId={team.id} /><FixturePreview /></>
}

function PlayerStatistics() {
  const candidate = usePplStore((state) => state.candidates.find((item) => item.name === "Mira Sen") ?? state.candidates[0])
  const team = usePplStore((state) => state.teams.find((item) => item.id === 2) ?? seedTeams[1])
  return <><PageHeader eyebrow="PLAYER / PERFORMANCE" title="Your season stats." description={`Personal match performance and gameplay attributes for ${candidate.name}.`} action={<StatusPill status="gold">SAMPLE STATS</StatusPill>} /><div className="demo-banner"><Sparkles size={16} /><span>All performance figures and player attributes are fictional demonstration data.</span><StatusPill status="gold">DEMO ONLY</StatusPill></div><div className="metrics-grid"><StatCard label="Runs scored" value="126" note="Across 3 illustrative innings" icon={TrendingUp} /><StatCard label="Wickets" value="03" note="Across 3 sample matches" icon={Target} tone="blue" /><StatCard label="Batting average" value="42.0" note="Fictional season average" icon={Activity} tone="green" /><StatCard label="Strike rate" value="142.3" note="Fictional gameplay stat" icon={Sparkles} tone="purple" /></div><SectionCard title={`${team.name} · match performance`}><SimpleTable headers={["ROUND", "OPPONENT", "BATTING", "BOWLING", "RESULT"]}><tr><td>01</td><td>Northern Hawks</td><td>48 (32)</td><td>1 / 24</td><td><StatusPill status="green">WON</StatusPill></td></tr><tr><td>01</td><td>Capital Chargers</td><td>31 (21)</td><td>2 / 19</td><td><StatusPill status="red">LOST</StatusPill></td></tr><tr><td>02</td><td>Western Wolves</td><td>47 (29)</td><td>0 / 21</td><td><StatusPill status="green">WON</StatusPill></td></tr></SimpleTable></SectionCard><div className="attribute-grid player-attribute-panel">{[["BATTING", candidate.batting], ["BOWLING", candidate.bowling], ["FIELDING", 86], ["OVERALL", candidate.rating]].map(([label, score]) => <div key={label}><span>{label}</span><strong>{score}</strong><i><b style={{ width: `${score}%` }} /></i></div>)}</div></>
}

function PlayerProfile() { const candidate = usePplStore((s) => s.candidates.find((c) => c.name === "Mira Sen") ?? s.candidates[0]); return <><PageHeader eyebrow="PLAYER / PROFILE" title="Your player card." description="A fictional player profile with gameplay-only attributes." /><div className="demo-banner"><Sparkles size={16} /><span>Fictional demonstration profile. Not a real participant, endorsement or political affiliation.</span><StatusPill status="gold">DEMO ONLY</StatusPill></div><SectionCard title="Player details" className="wide-card"><div className="player-profile-row profile-detail"><div className="player-monogram">{candidate.initials}</div><div><span>ALL-ROUNDER · INDIA</span><h2>{candidate.name}</h2><p>Coastal Royals · Fictional party metadata: {candidate.party}</p></div><StatusPill status="green">ACTIVE ROSTER</StatusPill></div><div className="attribute-grid">{[["BATTING", candidate.batting], ["BOWLING", candidate.bowling], ["FIELDING", 86], ["OVERALL", candidate.rating]].map(([label, score]) => <div key={label}><span>{label}</span><strong>{score}</strong><i><b style={{ width: `${score}%` }} /></i></div>)}</div></SectionCard><div className="metrics-grid compact-metrics"><StatCard label="Runs" value="126" note="Season to date" icon={TrendingUp} /><StatCard label="Wickets" value="03" note="Season to date" icon={Target} tone="blue" /><StatCard label="Strike rate" value="142.3" note="Illustrative stats" icon={Activity} tone="green" /><StatCard label="Best score" value="48" note="Against Northern Hawks" icon={Sparkles} tone="purple" /></div><FixturePreview /></> }

function UtilityModule({ role, slug, title }: { role: Role; slug: string; title: string }) { const notify = usePplStore((s) => s.notify); const [tab, setTab] = useState("Overview"); const users = [{ name: "Aarav Kapoor", email: "aarav@ppl.demo", role: "Team Owner", state: "Active" }, { name: "Mira Sen", email: "mira@ppl.demo", role: "Player", state: "Active" }, { name: "Guest Viewer", email: "viewer@ppl.demo", role: "Viewer", state: "Invited" }, { name: "Naina Desai", email: "naina@ppl.demo", role: "Team Owner", state: "Active" }];
  return <><PageHeader eyebrow={`${roleMeta[role].label.toUpperCase()} / ${slug.toUpperCase()}`} title={`${title}.`} description={slug === "users" ? "Manage demonstration account records and role assignments." : slug === "settings" ? "Configure local prototype settings for this fictional league." : slug === "transactions" ? "Franchise spending and roster activity in the demo auction." : "Sample season metrics for your current role."} action={slug === "users" && <button className="app-button primary" onClick={() => notify("Invite form is ready for a future backend integration.")}><Users size={15} /> Invite user</button>} />{slug === "users" ? <SectionCard title="League users" action={<StatusPill status="gold">DEMO ACCOUNTS</StatusPill>}><SimpleTable headers={["USER", "EMAIL", "ROLE", "STATUS", "ACTION"]}>{users.map((user) => <tr key={user.email}><td><strong>{user.name}</strong></td><td>{user.email}</td><td>{user.role}</td><td><StatusPill status={user.state === "Active" ? "green" : "blue"}>{user.state}</StatusPill></td><td><button className="table-link button-link" onClick={() => notify(`${user.name} role controls are a local demo.`)}>Manage <ArrowUpRight size={13} /></button></td></tr>)}</SimpleTable></SectionCard> : slug === "settings" ? <SectionCard title="Prototype settings" className="wide-card"><div className="settings-list">{[["League name", "Political Premier League"], ["Season", "Inaugural season · 2025"], ["Auction status", "Not started · simulation only"], ["Currency", "INR · Lakhs"]].map(([label, value]) => <label key={label}><span>{label.toUpperCase()}</span><input defaultValue={value} /></label>)}</div><button className="app-button primary" onClick={() => notify("Settings saved to this view only.")}>Save local settings</button></SectionCard> : <><div className="module-tabs" role="tablist">{["Overview", "By match", "By category"].map((item) => <button role="tab" aria-selected={tab === item} className={tab === item ? "selected" : ""} onClick={() => setTab(item)} key={item}>{item}</button>)}</div><div className="metrics-grid"><StatCard label="Total transactions" value="03" note="Fictional demo records" icon={TrendingUp} /><StatCard label="Total spend" value="₹ 32.8L" note="Across all franchises" icon={Activity} tone="blue" /><StatCard label="Average bid" value="₹ 10.9L" note="Sold candidate average" icon={Target} tone="green" /><StatCard label="Open candidates" value="06" note="Available in demo pool" icon={Users} tone="purple" /></div><RecentActivity /><CategoryCard candidates={usePplStore.getState().candidates} /><FixturePreview /></>}</> }
